package br.com.civicdrive;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;
/** Approved Civic Drive plasma texture cropped only from the supplied preview.
    Kept tiny (<4 KB) and decoded once; animated energy is drawn in Canvas. */
final class CivicPlasmaReference {
 private CivicPlasmaReference(){}
 static Bitmap decode(){
  try {
   byte[] bytes=Base64.decode("",Base64.DEFAULT);
   return BitmapFactory.decodeByteArray(bytes,0,bytes.length);
  } catch(Exception ignored){return null;}
 }
}
